const validate = (req, res, next) => { const errors = validationResult(req); return errors.isEmpty() ? next() : res.status(400).json({ success: false, message: 'Please check the highlighted fields.', errors: errors.array().map(({ path, msg }) => ({ field: path, message: msg })) }) }
const asyncRoute = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next)
const pageArgs = (query) => ({ page: Math.max(1, Number.parseInt(query.page, 10) || 1), limit: Math.min(50, Math.max(1, Number.parseInt(query.limit, 10) || 10)) })
const indiaDate = (value) => { if (typeof value !== 'string' || !/^\d{4}-\d\d-\d\dT\d\d:\d\d/.test(value) || /(?:Z|[+-]\d\d:\d\d)$/.test(value)) return new Date(value); return new Date(`${value.length === 16 ? `${value}:00` : value}+05:30`) }
const indiaCalendarDay = (date) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date)
const paged = async (model, filter, query, sort = { createdAt: -1 }) => { const { page, limit } = pageArgs(query); const [data, total] = await Promise.all([model.find(filter).sort(sort).skip((page - 1) * limit).limit(limit), model.countDocuments(filter)]); return { data, pagination: { page, limit, total, totalPages: Math.ceil(total / limit) } } }
